# ──────────────────────────────────────────────────────────────
#  LOAD MODELS (cached)
# ──────────────────────────────────────────────────────────────
@st.cache_resource(show_spinner="Loading MediGuru knowledge base…")
def load_system():
    index = faiss.read_index("vector_store/index.faiss")
    with open("vector_store/documents.pkl", "rb") as f:
        documents = pickle.load(f)
    embed_model = SentenceTransformer("all-MiniLM-L6-v2")
    return index, documents, embed_model

index, documents, embed_model = load_system()


# ──────────────────────────────────────────────────────────────
#  SESSION STATE
# ──────────────────────────────────────────────────────────────
if "messages" not in st.session_state:
    st.session_state.messages = []   # {role, content, conf?, docs?}


# ──────────────────────────────────────────────────────────────
#  RAG HELPER
# ──────────────────────────────────────────────────────────────
def retrieve_and_generate(query: str):
    """Run RAG pipeline; return (answer, confidence_pct, top_docs)."""

    # 1 · Embed query
    qvec = embed_model.encode([query], normalize_embeddings=True).astype("float32")

    # 2 · FAISS search
    k = 12
    distances, idxs = index.search(qvec, k)
    scores = distances[0]
    raw_docs = [documents[i] for i in idxs[0]]

    # 3 · Keyword re-rank
    query_terms = set(query.lower().split())
    def _rank(pair):
        doc, dist = pair
        kw = len(query_terms & set(doc.page_content.lower().split()))
        return kw + 1.0 / (dist + 1e-6)

    ranked   = sorted(zip(raw_docs, scores), key=_rank, reverse=True)
    top_docs = [d for d, _ in ranked[:3]]

    # 4 · Build context
    context = "\n\n".join(d.page_content for d in top_docs)[:1300]

    # 5 · Confidence (mean of top-3 similarities, clipped to [0,1])
    top_scores = [s for _, s in ranked[:3]]
    confidence_pct = round(min(float(np.mean(top_scores)) * 100, 100), 1)

    # 6 · Ollama prompt
    prompt = f"""You are MediGuru — a wise, calm, and knowledgeable AI medical assistant.
Answer the user\'s question clearly and compassionately using the context provided.
Write in plain, friendly language. Be concise. Only use bullet points if the question genuinely needs a list.
Never make up information outside the context.

Context:
{context}

User question: {query}"""

    response = ollama.chat(
        model="phi3",
        messages=[{"role": "user", "content": prompt}],
        options={"num_predict": 320, "temperature": 0.3}
    )
    answer = response["message"]["content"].strip()

    return answer, confidence_pct, top_docs


# ──────────────────────────────────────────────────────────────
#  PAGE RENDER
# ──────────────────────────────────────────────────────────────

# ── Header ──
st.markdown("""
<div class="mg-header">
    <div class="mg-logo-ring">🧘</div>
    <span class="mg-wordmark">MediGuru</span>
    <span class="mg-tagline">AI · Knowledge · Health · Wisdom</span>
    <div class="mg-rule"></div>
</div>
""", unsafe_allow_html=True)

# ── Disclaimer ──
st.markdown("""
<div class="mg-disc">
    ⚠️ <strong>Medical Disclaimer</strong> — MediGuru provides general health information only.
    It is not a substitute for professional medical advice, diagnosis, or treatment.
</div>
""", unsafe_allow_html=True)

# ──────────────────────────────────────────────────────────────
#  CHAT HISTORY
# ──────────────────────────────────────────────────────────────
if not st.session_state.messages:
    # Welcome state
    st.markdown("""
    <div class="mg-welcome">
        <span class="mg-welcome-icon">🩺</span>
        <div class="mg-welcome-h">How can MediGuru help you today?</div>
        <div class="mg-welcome-p">
            Ask me about symptoms, medications, conditions, or general wellness.
            I'll guide you with clarity and care.
        </div>
        <div class="chip-row">
            <span class="chip">🤧 Common cold remedies</span>
            <span class="chip">🩸 High blood pressure causes</span>
            <span class="chip">😴 Signs of sleep apnea</span>
            <span class="chip">🍎 Heart-healthy diet tips</span>
            <span class="chip">💊 Paracetamol vs Ibuprofen</span>
            <span class="chip">🧠 Anxiety disorder symptoms</span>
        </div>
    </div>
    """, unsafe_allow_html=True)

else:
    # Render full conversation
    st.markdown('<div class="chat-stream">', unsafe_allow_html=True)

    for msg in st.session_state.messages:
        role    = msg["role"]
        content = msg["content"]

        if role == "user":
            st.markdown(f"""
            <div class="msg-row user">
                <div class="av av-user">🙋</div>
                <div class="bubble user-b">{content}</div>
            </div>
            """, unsafe_allow_html=True)

        else:
            # AI bubble
            st.markdown(f"""
            <div class="msg-row">
                <div class="av av-ai">🤖</div>
                <div class="bubble ai-b">{content}</div>
            </div>
            """, unsafe_allow_html=True)

            # Confidence bar (if stored)
            if "conf" in msg:
                c = msg["conf"]
                st.markdown(f"""
                <div class="conf-block">
                    <span class="conf-tag">Relevance</span>
                    <div class="conf-rail">
                        <div class="conf-fill" style="width:{c}%"></div>
                    </div>
                    <span class="conf-num">{c:.0f}%</span>
                </div>
                """, unsafe_allow_html=True)

            # Sources (if stored)
            if msg.get("docs"):
                with st.expander("🔍 Knowledge Sources — Explainable AI"):
                    st.markdown(f"""
                    <div class="src-header">
                        📂 {len(msg["docs"])} documents retrieved
                        &nbsp;·&nbsp; Confidence: {msg.get("conf", 0):.0f}%
                    </div>
                    """, unsafe_allow_html=True)
                    for i, doc in enumerate(msg["docs"], 1):
                        src  = doc.metadata.get("source", f"Document {i}")
                        text = doc.page_content[:260].strip()
                        st.markdown(f"""
                        <div class="src-card">
                            <div class="src-name">
                                📄 Source {i}
                                <span class="src-badge">✓ retrieved</span>
                            </div>
                            <div style="font-size:0.70rem;color:#94a3b8;margin-bottom:5px">{src}</div>
                            <div class="src-snippet">{text}…</div>
                        </div>
                        """, unsafe_allow_html=True)

    st.markdown('</div>', unsafe_allow_html=True)


# ──────────────────────────────────────────────────────────────
#  CHAT INPUT
# ──────────────────────────────────────────────────────────────
query = st.chat_input("Ask about symptoms, conditions, medications, wellness…")

if query:
    # 1 · Append user turn immediately
    st.session_state.messages.append({"role": "user", "content": query})

    # 2 · Show user bubble
    st.markdown(f"""
    <div class="msg-row user">
        <div class="av av-user">🙋</div>
        <div class="bubble user-b">{query}</div>
    </div>
    """, unsafe_allow_html=True)

    # 3 · Run RAG + LLM
    with st.spinner("MediGuru is reflecting…"):
        answer, conf_pct, top_docs = retrieve_and_generate(query)

    # 4 · Show AI bubble
    st.markdown(f"""
    <div class="msg-row">
        <div class="av av-ai">🤖</div>
        <div class="bubble ai-b">{answer}</div>
    </div>
    <div class="conf-block">
        <span class="conf-tag">Relevance</span>
        <div class="conf-rail">
            <div class="conf-fill" style="width:{conf_pct}%"></div>
        </div>
        <span class="conf-num">{conf_pct:.0f}%</span>
    </div>
    """, unsafe_allow_html=True)

    # 5 · Sources expander
    with st.expander("🔍 Knowledge Sources — Explainable AI"):
        st.markdown(f"""
        <div class="src-header">
            📂 {len(top_docs)} documents retrieved
            &nbsp;·&nbsp; Confidence: {conf_pct:.0f}%
        </div>
        """, unsafe_allow_html=True)
        for i, doc in enumerate(top_docs, 1):
            src  = doc.metadata.get("source", f"Document {i}")
            text = doc.page_content[:260].strip()
            st.markdown(f"""
            <div class="src-card">
                <div class="src-name">
                    📄 Source {i}
                    <span class="src-badge">✓ retrieved</span>
                </div>
                <div style="font-size:0.70rem;color:#94a3b8;margin-bottom:5px">{src}</div>
                <div class="src-snippet">{text}…</div>
            </div>
            """, unsafe_allow_html=True)

    # 6 · Persist AI turn (with metadata for history render)
    st.session_state.messages.append({
        "role":    "assistant",
        "content": answer,
        "conf":    conf_pct,
        "docs":    top_docs,
    })

    # 7 · Rerun to re-render full chat cleanly
    st.rerun()